// Group ads by brand and collect new hooks/angles vs prior corpus
const rows = items.map(i => i.json);
const byBrand = {};
for (const row of rows) {
  if (!byBrand[row.brand_name]) byBrand[row.brand_name] = { hooks: new Set(), angles: new Set(), types: new Set(), count: 0 };
  byBrand[row.brand_name].count++;
  if (row.hook)       byBrand[row.brand_name].hooks.add(row.hook);
  if (row.core_angle) byBrand[row.brand_name].angles.add(row.core_angle);
  if (row.ad_type)    byBrand[row.brand_name].types.add(row.ad_type);
}
const weekStart = new Date();
weekStart.setDate(weekStart.getDate() - 7);
return Object.entries(byBrand).map(([brand, data]) => ({
  json: {
    brand_name: brand,
    week_start: weekStart.toISOString().split('T')[0],
    new_ad_count: data.count,
    new_hooks: [...data.hooks],
    new_angles: [...data.angles],
    summary_prompt: `Summarize in 2 sentences what ${brand} is doing in their ads this week: ${data.count} new ads. Hooks: ${[...data.hooks].join(', ')}. Angles: ${[...data.angles].join(', ')}. Formats: ${[...data.types].join(', ')}.`
  }
}));
